CREATE OR REPLACE FUNCTION public.block_delete_of_received_po()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_received numeric;
begin
  select coalesce(sum(qty_received),0) into v_received
    from purchase_order_lines where po_id = old.id;
  if v_received > 0 then
    raise exception 'Order % has received % already, so it cannot be deleted. Cancel it instead.',
      old.reference, v_received;
  end if;
  return old;
end $function$

CREATE OR REPLACE FUNCTION public.log_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old jsonb; v_new jsonb; v_id text; v_email text; v_sum text;
  v_parts text[] := '{}';
  v_key text; v_actor uuid;
begin
  -- Everything goes through jsonb. Naming columns directly (old.status, old.value) only
  -- compiles on the tables that have them, so one trigger function shared across eight
  -- tables fails at runtime on the first table missing a column.
  if tg_op <> 'INSERT' then v_old := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_new := to_jsonb(new); end if;
  v_id := coalesce(v_new->>'id', v_old->>'id', '');

  -- auth.uid() exists on Supabase and not in a plain Postgres. Never let the absence of a
  -- signed-in user, or anything else in here, stop the write it is recording.
  begin
    execute 'select auth.uid()' into v_actor;
    select email into v_email from auth.users where id = v_actor;
  exception when others then v_actor := null; v_email := null;
  end;

  if tg_op = 'INSERT' then
    v_sum := 'created';
  elsif tg_op = 'DELETE' then
    v_sum := 'deleted';
  else
    -- name the fields worth naming, and only those, so the log reads as English
    foreach v_key in array array['status','value','sell_rate','cost_rate','quantity',
                                 'amount','reference','paid_on','qty_ordered','qty_received']
    loop
      if v_old ? v_key and (v_old->>v_key) is distinct from (v_new->>v_key) then
        v_parts := v_parts || (replace(v_key,'_',' ') || ' ' ||
                   coalesce(nullif(v_old->>v_key,''),'blank') || ' to ' ||
                   coalesce(nullif(v_new->>v_key,''),'blank'));
      end if;
    end loop;
    v_sum := coalesce(nullif(array_to_string(v_parts, ', '), ''), 'edited');
  end if;

  begin
    insert into activity_log (actor, actor_email, table_name, row_id, action, summary)
    values (v_actor, v_email, tg_table_name, v_id, lower(tg_op), left(v_sum, 400));
  exception when others then null;   -- the log is never worth losing a real write over
  end;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.next_invoice_reference()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare n int; prefix text; suffix text; digits int;
begin
  update settings set value = (value::int + 1)::text
   where key = 'invoice_next_number'
  returning (value::int - 1) into n;
  select value into prefix from settings where key = 'invoice_prefix';
  select value into suffix from settings where key = 'invoice_suffix';
  select value::int into digits from settings where key = 'invoice_number_digits';
  return coalesce(prefix,'') || lpad(n::text, coalesce(digits,4), '0') || coalesce(suffix,'');
end $function$

CREATE OR REPLACE FUNCTION public.next_quotation_reference()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare n int; prefix text; suffix text; digits int;
begin
  update settings set value = (value::int + 1)::text
   where key = 'quote_next_number'
  returning (value::int - 1) into n;
  select value into prefix from settings where key = 'quote_prefix';
  select value into suffix from settings where key = 'quote_suffix';
  select value::int into digits from settings where key = 'quote_number_digits';
  return prefix || lpad(n::text, digits, '0') || suffix;
end $function$

CREATE OR REPLACE FUNCTION public.next_quotation_reference(p_office uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare n int; o record;
begin
  if p_office is null then select id into p_office from offices where code = 'DXB'; end if;
  update offices set quote_next = quote_next + 1
   where id = p_office
  returning quote_prefix, quote_suffix, quote_digits, quote_next - 1 as n into o;
  if not found then raise exception 'There is no office with that id.'; end if;
  return o.quote_prefix || lpad(o.n::text, o.quote_digits, '0') || o.quote_suffix;
end $function$

CREATE OR REPLACE FUNCTION public.office_must_match_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_parent uuid;
begin
  if tg_table_name in ('stock','stock_movements') then
    select office_id into v_parent from warehouses where id = new.warehouse_id;
  else
    select office_id into v_parent from projects where id = new.project_id;
  end if;
  if v_parent is not null and new.office_id is distinct from v_parent then
    new.office_id := v_parent;      -- the parent is the truth, so follow it silently
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.receive_po_line(p_line_id uuid, p_qty numeric, p_warehouse_id uuid, p_moved_on date DEFAULT CURRENT_DATE, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_line purchase_order_lines%rowtype;
  v_po   purchase_orders%rowtype;
  v_left numeric;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'Receive a quantity greater than zero.';
  end if;
  select * into v_line from purchase_order_lines where id = p_line_id;
  if not found then raise exception 'That order line no longer exists.'; end if;
  select * into v_po from purchase_orders where id = v_line.po_id;

  v_left := v_line.qty_ordered - v_line.qty_received;
  if p_qty > v_left + 0.001 then
    raise exception 'Only % % of % are still outstanding on this line. Amend the order first.',
      round(v_left,3), v_line.unit, v_line.description;
  end if;
  if v_line.product_id is null then
    raise exception 'This line is not linked to a catalogue product, so it cannot go into stock.';
  end if;
  if coalesce(p_warehouse_id, v_po.warehouse_id) is null then
    raise exception 'Say which warehouse it went into.';
  end if;

  insert into stock_movements (product_id, warehouse_id, direction, quantity,
                               project_id, reference, note, moved_on)
  values (v_line.product_id, coalesce(p_warehouse_id, v_po.warehouse_id), 'in', p_qty,
          v_po.project_id, v_po.reference,
          coalesce(p_note, 'Received against ' || v_po.reference), p_moved_on);

  update purchase_order_lines set qty_received = qty_received + p_qty where id = p_line_id;

  update purchase_orders set status =
    case when (select bool_and(qty_received >= qty_ordered - 0.001)
                 from purchase_order_lines where po_id = v_po.id)
         then 'received'::po_status else 'part'::po_status end
   where id = v_po.id and status in ('sent','confirmed','part');
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_approval_to_subject()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare granted boolean;
begin
  granted := (new.status = 'approved');

  if new.kind = 'product_dcd' and new.product_id is not null then
    update products
       set dcd_approved = granted,
           dcd_ref      = case when granted then coalesce(new.reference, dcd_ref) else dcd_ref end,
           dcd_expiry   = case when granted then new.expires_on else dcd_expiry end
     where id = new.product_id;

  elsif new.kind = 'warehouse_storage' and new.warehouse_id is not null then
    update warehouses
       set dcd_certified       = granted,
           dcd_certificate_ref = case when granted then coalesce(new.reference, dcd_certificate_ref)
                                      else dcd_certificate_ref end,
           dcd_expiry          = case when granted then new.expires_on else dcd_expiry end
     where id = new.warehouse_id;
  end if;

  return new;
end $function$
